window.COURSE = {"title":"Produktionsmission: Engpass meistern","subtitle":"Relativer Deckungsbeitrag · FOS Klasse 12","products":[{"id":"basic","name":"Basic","price":95,"kv":55,"max":400,"time":8},{"id":"city","name":"City","price":145,"kv":80,"max":300,"time":10},{"id":"studio","name":"Studio","price":190,"kv":110,"max":200,"time":20},{"id":"pro","name":"Pro","price":240,"kv":135,"max":150,"time":15}],"capacity":9250,"fixed":38000,"chapters":[{"id":"basis","title":"Der Stückdeckungsbeitrag","icon":"🧮","lead":"Sie arbeiten im Planungsteam einer Leipziger Leuchtenproduktion. Vor einer Engpassentscheidung müssen Sie verstehen, wie viel jedes verkaufte Produkt beiträgt.","definition":"<b>Stückdeckungsbeitrag (db)</b> = <b>Nettoverkaufspreis</b> − <b>variable Stückkosten</b>. Er zeigt den Beitrag eines verkauften Stücks zur <b>Deckung der Fixkosten</b> und anschließend zum Gewinn. <b>Variable Kosten</b> verändern sich mit der Ausbringungsmenge; die betrachteten <b>Fixkosten</b> bleiben im relevanten Bereich unverändert.","example":"<b>Beispiel einer Werkstattleuchte:</b> 89,00 € (Nettoverkaufspreis) − 51,00 € (variable Stückkosten) = <b>38,00 €/Stück</b>. Berechnen Sie anschließend die anderen Modelle in der Übungsstation.","questions":[{"id":"b01","afb":1,"type":"matrix","prompt":"Füllen Sie für die vier Leuchtenmodelle die noch offenen Stückdeckungsbeiträge in der Tabelle aus.","answer":{"basic:db":40,"city:db":65,"studio:db":80,"pro:db":105},"solution":"<b>Stück-DB = Preis − variable Stückkosten:</b> Basic: 95 − 55 = <b>40 €/St.</b>; City: 145 − 80 = <b>65 €/St.</b>; Studio: 190 − 110 = <b>80 €/St.</b>; Pro: 240 − 135 = <b>105 €/St.</b>.","hint":"Bestimmen Sie zuerst, welche Größen bereits vorgegeben sind und welche Größe jede Tabellenspalte berechnet.","grid":{"columns":[{"id":"preis","title":"Netto-Preis €/St.","hint":""},{"id":"kv","title":"Var. Kosten €/St.","hint":""},{"id":"db","title":"Stück-DB €/St.","hint":"db = Nettoverkaufspreis − variable Stückkosten. Prüfen Sie den Unterschied der beiden Werte."}],"rows":[{"id":"basic","label":"Basic","given":{"preis":95,"kv":55},"expected":{"db":40},"hint":"Basic: Ziehen Sie die variablen Stückkosten vom Nettoverkaufspreis ab; die Fixkosten werden hier noch nicht berücksichtigt."},{"id":"city","label":"City","given":{"preis":145,"kv":80},"expected":{"db":65},"hint":"City: Ziehen Sie die variablen Stückkosten vom Nettoverkaufspreis ab; die Fixkosten werden hier noch nicht berücksichtigt."},{"id":"studio","label":"Studio","given":{"preis":190,"kv":110},"expected":{"db":80},"hint":"Studio: Ziehen Sie die variablen Stückkosten vom Nettoverkaufspreis ab; die Fixkosten werden hier noch nicht berücksichtigt."},{"id":"pro","label":"Pro","given":{"preis":240,"kv":135},"expected":{"db":105},"hint":"Pro: Ziehen Sie die variablen Stückkosten vom Nettoverkaufspreis ab; die Fixkosten werden hier noch nicht berücksichtigt."}]}},{"id":"b02","afb":1,"type":"single","prompt":"Was sagt der Stückdeckungsbeitrag aus?","answer":"b","solution":"Der Stückdeckungsbeitrag zeigt, welcher Betrag pro Stück zur Deckung der Fixkosten und danach zum Gewinn beitragen kann.","hint":"Er ist nicht identisch mit dem Stückgewinn.","options":[["a","Gewinn nach Abzug aller fixen Kosten je Stück"],["b","Nettoverkaufspreis minus variable Stückkosten"],["c","Umsatz minus alle Fixkosten"]]},{"id":"b03","afb":2,"type":"matrix","prompt":"Ein Betrieb prüft drei Varianten seiner LED-Arbeitsplatzleuchte. Berechnen Sie für jede Variante den Stückdeckungsbeitrag.","answer":{"eco:db":75,"flex:db":60,"plus:db":85},"solution":"Eco: 198 € (Preis) − 123 € (variable Stückkosten) = <b>75 €/St.</b>; Flex: 172 − 112 = <b>60 €/St.</b>; Plus: 245 − 160 = <b>85 €/St.</b>.","hint":"In jeder Zeile wird derselbe Rechenweg angewandt. Es werden keine Fixkosten verteilt.","grid":{"columns":[{"id":"preis","title":"Netto-Preis €/St.","hint":""},{"id":"kv","title":"Var. Kosten €/St.","hint":""},{"id":"db","title":"Stück-DB €/St.","hint":"db = Nettoverkaufspreis − variable Stückkosten. Prüfen Sie den Unterschied der beiden Werte."}],"rows":[{"id":"eco","label":"Eco","given":{"preis":198,"kv":123},"expected":{"db":75},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"flex","label":"Flex","given":{"preis":172,"kv":112},"expected":{"db":60},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"plus","label":"Plus","given":{"preis":245,"kv":160},"expected":{"db":85},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"b04","afb":2,"type":"multi","prompt":"Ordnen Sie die Kostenarten richtig zu. Welche Kosten sind im beschriebenen Fall typischerweise variabel?","answer":["material","pack"],"solution":"Typisch variabel sind unmittelbar verbrauchtes Fertigungsmaterial und eine stückbezogene Verpackung. Die monatliche Hallenmiete und das feste Verwaltungsgehalt sind im betrachteten Kapazitätsbereich fix.","hint":"Prüfen Sie, welche Kosten sich mit jedem zusätzlich gefertigten Stück erhöhen.","options":[["material","Material je hergestellter Leuchte"],["miete","Unveränderte Hallenmiete"],["pack","Einzelverpackung je Leuchte"],["gehalt","Festes Gehalt der Verwaltung"]]},{"id":"b05","afb":2,"type":"match","prompt":"Ordnen Sie die Begriffe ihrer Bedeutung zu.","answer":["preis","variabel","fix","db"],"solution":"<b>Preis:</b> Nettoverkaufspreis; <b>variable Stückkosten:</b> mengenabhängige Kosten je Stück; <b>Fixkosten:</b> im Betrachtungsbereich unabhängig von der Menge; <b>db:</b> Preis − variable Stückkosten.","hint":"Jeder Begriff hat genau eine passende Beschreibung.","pairs":[["preis","Nettoverkaufspreis je Stück"],["variabel","Mengenabhängige Kosten pro Stück"],["fix","Innerhalb des betrachteten Bereichs mengenunabhängig"],["db","Preis abzüglich variabler Stückkosten"]]},{"id":"b06","afb":2,"type":"text","prompt":"Erläutern Sie in eigenen Worten, weshalb ein positiver Stückdeckungsbeitrag noch nicht mit Gewinn pro Stück gleichzusetzen ist.","answer":"self","solution":"Der <b>Stück-DB</b> ist der Beitrag nach Abzug der <b>variablen</b> Stückkosten. Die <b>Fixkosten</b> sind noch nicht abgezogen; erst ihre Deckung führt zu einem Gewinn.","hint":"Nennen Sie, welche Kosten im Stück-DB noch fehlen."},{"id":"b07","afb":3,"type":"text","prompt":"Ein Kollege sagt: „Das Modell Studio ist mit 80 € Stück-DB stets wirtschaftlicher als City mit 65 €.“ Beurteilen Sie diese Aussage für eine begrenzte Montagezeit.","answer":"self","solution":"Die Aussage ist <b>nicht allgemein richtig</b>. Studio benötigt 20 min je Stück: 80 € ÷ 20 = <b>4 €/min</b>. City benötigt 10 min: 65 € ÷ 10 = <b>6,50 €/min</b>. Beim Montageengpass ist City je knapper Minute günstiger.","hint":"Vergleichen Sie den DB pro Minute und nicht nur pro Stück."},{"id":"b08","afb":3,"type":"single","prompt":"Ein Unternehmen kann in einer Engpassstunde Produkt A (70 € DB / 35 min) oder Produkt B (45 € DB / 10 min) fertigen. Welches Produkt ist bei ausreichender Nachfrage vorrangig?","answer":"b","solution":"Produkt A: 70 € ÷ 35 min = 2 €/min; Produkt B: 45 € ÷ 10 min = 4,50 €/min. <b>Produkt B</b> hat Vorrang.","hint":"Vergleichen Sie den relativen Deckungsbeitrag.","options":[["a","Produkt A, wegen des höheren Stück-DB"],["b","Produkt B, wegen des höheren DB je Minute"],["c","Beide sind immer gleich gut"]]}]},{"id":"engpass","title":"Den Engpass erkennen","icon":"⏱️","lead":"Für die Leuchten liegen maximale Absatzmengen und Montagezeiten vor. Sie prüfen, ob die vorhandene Anlage sämtliche Nachfrage bedienen könnte.","definition":"Ein <b>Engpass</b> liegt vor, wenn die zur Befriedigung der Nachfrage benötigte <b>Kapazität</b> größer ist als die <b>verfügbare Kapazität</b>. <b>Zeitbedarf je Produkt</b> = maximale Absatzmenge · Zeit je Stück. <b>Gesamtzeitbedarf</b> = Summe der Einzelbedarfe. Beachten Sie immer einheitliche Zeiteinheiten.","example":"<b>Beispiel:</b> 140 Geräte (Absatzgrenze) · 6 min/Stück (Montagezeit) = <b>840 Minuten</b> Bedarf. Erst die Summe aller Modelle zeigt, ob die verfügbare Kapazität ausreicht.","questions":[{"id":"e01","afb":1,"type":"matrix","prompt":"Berechnen Sie die noch offenen Montagezeitbedarfe bei vollständiger Ausschöpfung der Absatzgrenzen.","answer":{"city:bedarf":3000,"studio:bedarf":4000,"pro:bedarf":2250},"solution":"Basic: 400 · 8 = <b>3.200 min</b> (vorgegeben); City: 300 · 10 = <b>3.000 min</b>; Studio: 200 · 20 = <b>4.000 min</b>; Pro: 150 · 15 = <b>2.250 min</b>.","hint":"Die Zeile Basic ist als Orientierung bereits ausgefüllt. Berechnen Sie die übrigen Zeilen mit derselben Formel.","grid":{"columns":[{"id":"max","title":"Max. Absatz (St.)","hint":""},{"id":"min","title":"Zeit (min/St.)","hint":""},{"id":"bedarf","title":"Zeitbedarf (min)","hint":"Zeitbedarf = maximal absetzbare Menge · Montagezeit je Stück."}],"rows":[{"id":"basic","label":"Basic","given":{"max":400,"min":8,"bedarf":3200},"expected":{},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"max":300,"min":10},"expected":{"bedarf":3000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"max":200,"min":20},"expected":{"bedarf":4000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"max":150,"min":15},"expected":{"bedarf":2250},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"e02","afb":1,"type":"truefalse","prompt":"Liegt bereits dann ein Engpass vor, wenn ein Modell einen besonders hohen Stückdeckungsbeitrag besitzt?","answer":false,"solution":"<b>Falsch.</b> Ein Engpass entsteht erst, wenn der benötigte Umfang einer knappen Ressource die verfügbare Kapazität übersteigt.","hint":"Ein hoher DB allein sagt nichts über den Zeitbedarf."},{"id":"e03","afb":2,"type":"matrix","prompt":"Berechnen Sie alle Zeitbedarfe und den Gesamtbedarf für die vier Modelle. Nutzen Sie die zusätzliche Summenzeile.","answer":{"basic:bedarf":3200,"city:bedarf":3000,"studio:bedarf":4000,"pro:bedarf":2250,"summe:bedarf":12450},"solution":"Basic 400 · 8 = 3.200 min; City 300 · 10 = 3.000 min; Studio 200 · 20 = 4.000 min; Pro 150 · 15 = 2.250 min. <b>Summe:</b> 3.200 + 3.000 + 4.000 + 2.250 = <b>12.450 min</b>.","hint":"Ermitteln Sie zuerst die vier Einzelbedarfe und danach die Summe. Vergleichen Sie bei der nächsten Frage Bedarf und Kapazität.","grid":{"columns":[{"id":"max","title":"Max. Absatz (St.)","hint":""},{"id":"min","title":"Zeit (min/St.)","hint":""},{"id":"bedarf","title":"Zeitbedarf (min)","hint":"Zeitbedarf = maximal absetzbare Menge · Montagezeit je Stück."}],"rows":[{"id":"basic","label":"Basic","given":{"max":400,"min":8},"expected":{"bedarf":3200},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"max":300,"min":10},"expected":{"bedarf":3000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"max":200,"min":20},"expected":{"bedarf":4000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"max":150,"min":15},"expected":{"bedarf":2250},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"summe","label":"SUMME","given":{},"expected":{"bedarf":12450},"hint":"Addieren Sie nur die vier bereits ermittelten Minutenbedarfe und nicht die Stückzahlen."}]}},{"id":"e04","afb":2,"type":"number","prompt":"Wie viele Minuten fehlen für die vollständige Bedienung der Nachfrage, wenn 9.250 min zur Verfügung stehen?","answer":3200,"solution":"12.450 min (Gesamtzeitbedarf) − 9.250 min (verfügbare Montagekapazität) = <b>3.200 min Fehlbedarf</b>.","hint":"Vergleichen Sie Bedarf und Kapazität."},{"id":"e05","afb":2,"type":"single","prompt":"Eine Anlage ist 140 Stunden verfügbar. Wie viele Minuten sind dies?","answer":"a","solution":"140 h (Kapazität) · 60 min/h = <b>8.400 min</b>.","hint":"Eine Stunde enthält 60 Minuten.","options":[["a","8.400 Minuten"],["b","14.000 Minuten"],["c","2.333 Minuten"]]},{"id":"e06","afb":2,"type":"multi","prompt":"Welche der folgenden Umstände können zu einem betrieblichen Engpass führen?","answer":["ausfall","personal","material"],"solution":"Ein Maschinenausfall, fehlendes Fachpersonal und nicht ausreichend verfügbares Material können Ressourcen verknappen. Ein höherer Nettoverkaufspreis allein begründet keinen Kapazitätsengpass.","hint":"Denken Sie an Produktionsfaktoren.","options":[["ausfall","Ausfall einer wichtigen Montagemaschine"],["preis","Höherer Verkaufspreis eines Produkts"],["personal","Zu wenig qualifiziertes Personal"],["material","Begrenzte Materiallieferung"]]},{"id":"e07","afb":3,"type":"text","prompt":"Für eine neue Produktionswoche werden 6.000 Maschinenminuten benötigt; verfügbar sind 6.500 Minuten. Beurteilen Sie, ob nach den vorliegenden Angaben ein Engpass besteht und welche Produktionsentscheidung daraus folgt.","answer":"self","solution":"<b>Kein Engpass:</b> 6.000 min (Bedarf) ≤ 6.500 min (Kapazität). Die Nachfrage kann vollständig hergestellt werden; eine Priorisierung der Produkte nach relativem DB ist hierfür <b>nicht notwendig</b>. Es bleiben 500 min frei.","hint":"Rechnen Sie die Differenz aus und leiten Sie daraus eine Konsequenz ab."},{"id":"e08","afb":3,"type":"text","prompt":"Die Montagekapazität von LichtForm beträgt 9.250 min. Die Vertriebsleitung möchte alle Absatzgrenzen vollständig bedienen. Prüfen Sie diese Forderung rechnerisch und schlagen Sie eine passende Vorgehensweise vor.","answer":"self","solution":"12.450 min (Bedarf) − 9.250 min (Kapazität) = <b>3.200 min Fehlbedarf</b>. Die Forderung ist ohne Erweiterung <b>nicht erfüllbar</b>. Deshalb muss die knappe Zeit nach dem <b>relativen Deckungsbeitrag</b> verteilt werden, um das Ergebnis zu verbessern.","hint":"Nicht nur Engpass feststellen: Konsequenz für die Reihenfolge begründen."}]},{"id":"rang","title":"Relativen DB und Rangfolge bestimmen","icon":"🏆","lead":"Bei einer knappen Montageanlage ist entscheidend, wie viel Deckungsbeitrag pro Montageminute erwirtschaftet wird.","definition":"Der <b>relative Deckungsbeitrag</b> ist der <b>Stückdeckungsbeitrag je Engpasseinheit</b>. Bei einem Zeitengpass gilt: <b>relativer DB = Stück-DB ÷ Minuten je Stück</b>. Ein höherer relativer DB bedeutet einen höheren Beitrag je eingesetzter knapper Minute. Daraus entsteht die <b>absteigende Fertigungsrangfolge</b>.","example":"<b>Beispiel:</b> 60 € (Stück-DB) ÷ 12 min/Stück (Montagezeit) = <b>5,00 €/min</b>. Der höhere relative DB erhält bei einem Engpass Vorrang.","questions":[{"id":"r01","afb":1,"type":"matrix","prompt":"Tragen Sie für alle vier Leuchten den relativen Deckungsbeitrag sowie den Rang in der Montageplanung ein.","answer":{"basic:rel":5,"basic:rang":3,"city:rel":6.5,"city:rang":2,"studio:rel":4,"studio:rang":4,"pro:rel":7,"pro:rang":1},"solution":"Basic: 40 ÷ 8 = <b>5,00 €/min (Rang 3)</b>; City: 65 ÷ 10 = <b>6,50 €/min (Rang 2)</b>; Studio: 80 ÷ 20 = <b>4,00 €/min (Rang 4)</b>; Pro: 105 ÷ 15 = <b>7,00 €/min (Rang 1)</b>. Reihenfolge: Pro → City → Basic → Studio.","hint":"Berechnen Sie zuerst alle €/min-Werte, erst danach vergeben Sie die Ränge.","grid":{"columns":[{"id":"db","title":"Stück-DB €/St.","hint":""},{"id":"min","title":"Zeit min/St.","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Relativer DB = Stück-DB ÷ Zeit je Stück. Alle Zeiten müssen dieselbe Einheit haben."},{"id":"rang","title":"Rang","hint":"Rang 1 erhält der höchste relative DB; anschließend absteigend ordnen."}],"rows":[{"id":"basic","label":"Basic","given":{"db":40,"min":8},"expected":{"rel":5,"rang":3},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"db":65,"min":10},"expected":{"rel":6.5,"rang":2},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"db":80,"min":20},"expected":{"rel":4,"rang":4},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"db":105,"min":15},"expected":{"rel":7,"rang":1},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"r02","afb":1,"type":"order","prompt":"Ordnen Sie die vier Leuchten von Rang 1 (zuerst) bis Rang 4 (zuletzt).","answer":["pro","city","basic","studio"],"solution":"<b>Pro → City → Basic → Studio.</b> Relative DB: Pro 7,00; City 6,50; Basic 5,00; Studio 4,00 €/min.","hint":"Ordnen Sie absteigend nach €/min.","items":[["basic","Basic"],["studio","Studio"],["pro","Pro"],["city","City"]]},{"id":"r03","afb":2,"type":"matrix","prompt":"Prüfen Sie drei Leuchtenvarianten einer zweiten Fertigungslinie: Berechnen Sie die relativen Deckungsbeiträge und die Reihenfolge.","answer":{"urban:rel":6,"urban:rang":2,"smart:rel":8,"smart:rang":1,"mini:rel":5,"mini:rang":3},"solution":"Urban: 48 € ÷ 8 min = <b>6 €/min (Rang 2)</b>; Smart: 72 € ÷ 9 min = <b>8 €/min (Rang 1)</b>; Mini: 55 € ÷ 11 min = <b>5 €/min (Rang 3)</b>.","hint":"Ein höherer Stückdeckungsbeitrag führt nur dann zum höheren Rang, wenn er relativ zur benötigten Zeit ebenfalls höher ist.","grid":{"columns":[{"id":"db","title":"Stück-DB €/St.","hint":""},{"id":"min","title":"Zeit min/St.","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Relativer DB = Stück-DB ÷ Zeit je Stück. Alle Zeiten müssen dieselbe Einheit haben."},{"id":"rang","title":"Rang","hint":"Rang 1 erhält der höchste relative DB; anschließend absteigend ordnen."}],"rows":[{"id":"urban","label":"Urban","given":{"db":48,"min":8},"expected":{"rel":6,"rang":2},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"smart","label":"Smart","given":{"db":72,"min":9},"expected":{"rel":8,"rang":1},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"mini","label":"Mini","given":{"db":55,"min":11},"expected":{"rel":5,"rang":3},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"r04","afb":2,"type":"match","prompt":"Ordnen Sie den vier Leuchten ihren relativen Deckungsbeitrag zu.","answer":["basic","studio","pro","city"],"solution":"Basic = <b>5,00 €/min</b>, City = <b>6,50 €/min</b>, Studio = <b>4,00 €/min</b>, Pro = <b>7,00 €/min</b>.","hint":"Berechnen Sie Stück-DB ÷ Montagezeit.","pairs":[["basic","5,00 €/min"],["studio","4,00 €/min"],["pro","7,00 €/min"],["city","6,50 €/min"]]},{"id":"r05","afb":2,"type":"matrix","prompt":"Ermitteln Sie aus Stückdeckungsbeitrag und Prüfzeit die relativen Deckungsbeiträge der LED-Platinen.","answer":{"p1:rel":6.5,"p1:rang":2,"p2:rel":7.5,"p2:rang":1,"p3:rel":5,"p3:rang":3},"solution":"P1: 78 ÷ 12 = <b>6,50 €/min (Rang 2)</b>; P2: 60 ÷ 8 = <b>7,50 €/min (Rang 1)</b>; P3: 105 ÷ 21 = <b>5 €/min (Rang 3)</b>.","hint":"Bestimmen Sie zuerst, welche Größen bereits vorgegeben sind und welche Größe jede Tabellenspalte berechnet.","grid":{"columns":[{"id":"db","title":"Stück-DB €/St.","hint":""},{"id":"min","title":"Zeit min/St.","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Relativer DB = Stück-DB ÷ Zeit je Stück. Alle Zeiten müssen dieselbe Einheit haben."},{"id":"rang","title":"Rang","hint":"Rang 1 erhält der höchste relative DB; anschließend absteigend ordnen."}],"rows":[{"id":"p1","label":"P1","given":{"db":78,"min":12},"expected":{"rel":6.5,"rang":2},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"p2","label":"P2","given":{"db":60,"min":8},"expected":{"rel":7.5,"rang":1},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"p3","label":"P3","given":{"db":105,"min":21},"expected":{"rel":5,"rang":3},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"r06","afb":2,"type":"multi","prompt":"Welche Aussagen zur Fertigungsrangfolge sind bei einem einzigen Engpass zutreffend?","answer":["rel","max","zeit"],"solution":"Die Reihenfolge richtet sich nach <b>relativem DB</b>. Je Produkt darf höchstens die <b>Absatzgrenze</b> ausgeschöpft werden. Die verwendete Zeit muss die <b>Gesamtkapazität</b> einhalten. Die höchsten Preise sind nicht automatisch vorrangig.","hint":"Prüfen Sie Engpass und Absatzgrenzen.","options":[["rel","Die Reihenfolge wird nach dem relativen DB gebildet."],["preis","Das Produkt mit dem höchsten Verkaufspreis steht immer zuerst."],["max","Absatzobergrenzen dürfen nicht überschritten werden."],["zeit","Der Gesamtzeitbedarf der ausgewählten Mengen ist begrenzt."]]},{"id":"r07","afb":3,"type":"text","prompt":"Der Vertrieb möchte Studio vor City produzieren, weil Studio einen höheren Stückdeckungsbeitrag hat. Widerlegen Sie die Entscheidung rechnerisch und erklären Sie die wirtschaftliche Konsequenz.","answer":"self","solution":"Studio: 80,00 € ÷ 20 min = <b>4,00 €/min</b>; City: 65,00 € ÷ 10 min = <b>6,50 €/min</b>. City erzielt 2,50 € mehr DB pro knapper Minute und ist deshalb vorrangig.","hint":"Rechnen Sie für beide Modelle den DB je Minute aus."},{"id":"r08","afb":3,"type":"single","prompt":"Produkt X erzielt 110 € Stück-DB bei 20 min; Produkt Y erzielt 63 € Stück-DB bei 9 min. Welche Priorität ist richtig?","answer":"y","solution":"X: 110 € ÷ 20 = 5,50 €/min; Y: 63 € ÷ 9 = 7,00 €/min. <b>Y steht vor X</b>.","hint":"Rechnen Sie beide relativen Deckungsbeiträge aus.","options":[["x","X vor Y, weil 110 € höher als 63 € sind"],["y","Y vor X, weil 7,00 €/min höher als 5,50 €/min sind"],["g","Beide müssen stets gleichzeitig produziert werden"]]}]},{"id":"programm","title":"Das optimale Produktionsprogramm","icon":"🏭","lead":"Sie verteilen die knappe Montagezeit Schritt für Schritt auf die vier Modelle. Begonnen wird mit dem höchsten relativen DB.","definition":"<b>Optimales Produktionsprogramm:</b> die Produktionsmengen, mit denen unter den vorliegenden Annahmen (ein Engpass, konstante DB, begrenzte Nachfrage) der <b>Gesamtdeckungsbeitrag</b> maximiert wird. Vorgehen: <b>1.</b> Rang 1 bis zur Absatzgrenze fertigen, <b>2.</b> Restzeit abziehen, <b>3.</b> nächstes Modell, <b>4.</b> bei begrenzter Restzeit nur die <b>ganze</b> herstellbare Stückzahl einsetzen.","example":"<b>Beispiel:</b> Pro nutzt 150 Stück · 15 min = 2.250 min. Rest: 9.250 − 2.250 = 7.000 min. City nutzt weitere 3.000 min, Basic weitere 3.200 min; für Studio bleiben 800 min, also <b>40 Stück</b>.","questions":[{"id":"p01","afb":1,"type":"number","prompt":"Nach vollständiger Produktion von Pro (150 Stück) verbleiben wie viele Minuten?","answer":7000,"solution":"9.250 min (Gesamtkapazität) − 150 Stück (Pro-Absatzgrenze) · 15 min/Stück = <b>7.000 min</b>.","hint":"Erst 150 · 15, dann von 9.250 abziehen."},{"id":"p02","afb":1,"type":"single","prompt":"Mit welchem Modell beginnen Sie das gewinnoptimale Produktionsprogramm?","answer":"pro","solution":"Mit <b>Pro</b>, da es mit 7,00 €/min den höchsten relativen DB besitzt.","hint":"Wählen Sie Rang 1.","options":[["basic","Basic"],["city","City"],["studio","Studio"],["pro","Pro"]]},{"id":"p03","afb":2,"type":"matrix","prompt":"Vervollständigen Sie die schrittweise Maschinenbelegung. Die erste Zeile (Pro) ist vorgerechnet. Startkapazität: 9.250 min.","answer":{"city:menge":300,"city:used":3000,"city:rest":4000,"basic:menge":400,"basic:used":3200,"basic:rest":800,"studio:menge":40,"studio:used":800,"studio:rest":0},"solution":"Pro: 150 · 15 = 2.250 min, Rest 7.000 min. City: 300 · 10 = 3.000 min, Rest <b>4.000 min</b>. Basic: 400 · 8 = 3.200 min, Rest <b>800 min</b>. Studio: 800 min ÷ 20 min/St. = <b>40 St.</b>; Zeit 40 · 20 = 800 min, Rest <b>0 min</b>.","hint":"Arbeiten Sie in Rangfolge von oben nach unten. Die Restzeit wird nach jeder Produktgruppe neu berechnet.","grid":{"columns":[{"id":"rang","title":"Rang","hint":""},{"id":"model","title":"Modell","hint":""},{"id":"max","title":"Max. Absatz St.","hint":""},{"id":"min","title":"min/St.","hint":""},{"id":"menge","title":"Planmenge St.","hint":"Nehmen Sie höchstens die Absatzgrenze und höchstens so viele Stück wie in die Restkapazität passen."},{"id":"used","title":"Zeit genutzt (min)","hint":"Genutzte Zeit = Planmenge · Minuten je Stück."},{"id":"rest","title":"Restzeit (min)","hint":"Restzeit = Rest aus vorheriger Zeile − genutzte Zeit."}],"rows":[{"id":"pro","label":"Pro","given":{"rang":1,"model":"Pro","max":150,"min":15,"menge":150,"used":2250,"rest":7000},"expected":{},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"rang":2,"model":"City","max":300,"min":10},"expected":{"menge":300,"used":3000,"rest":4000},"hint":"Die Restzeit nach Pro beträgt 7.000 min. Prüfen Sie, ob 300 City-Leuchten vollständig hineinpassen."},{"id":"basic","label":"Basic","given":{"rang":3,"model":"Basic","max":400,"min":8},"expected":{"menge":400,"used":3200,"rest":800},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"rang":4,"model":"Studio","max":200,"min":20},"expected":{"menge":40,"used":800,"rest":0},"hint":"Prüfen Sie zuerst die noch freien Minuten, dann teilen Sie durch 20 min je Stück."}]}},{"id":"p04","afb":2,"type":"matrix","prompt":"Füllen Sie die komplette Produktionstabelle aus: zuerst Stück-DB und relativen DB, danach Rangfolge, Produktionsmengen und tatsächlich genutzte Montagezeit. Es stehen 9.250 min zur Verfügung.","answer":{"basic:db":40,"basic:rel":5,"basic:rang":3,"basic:menge":400,"basic:used":3200,"city:db":65,"city:rel":6.5,"city:rang":2,"city:menge":300,"city:used":3000,"studio:db":80,"studio:rel":4,"studio:rang":4,"studio:menge":40,"studio:used":800,"pro:db":105,"pro:rel":7,"pro:rang":1,"pro:menge":150,"pro:used":2250},"solution":"Rangfolge: Pro (7 €/min), City (6,50 €/min), Basic (5 €/min), Studio (4 €/min). <b>Plan:</b> Pro 150 · 15 = 2.250 min; City 300 · 10 = 3.000 min; Basic 400 · 8 = 3.200 min; Studio 40 · 20 = 800 min. <b>9.250 min vollständig genutzt.</b>","hint":"Zuerst DB und Rang berechnen. Planmengen erst im zweiten Schritt zuweisen; es gilt ein einziger Maschinenengpass.","fields":["Basic (St.)","City (St.)","Studio (St.)","Pro (St.)"],"grid":{"columns":[{"id":"preis","title":"Preis €/St.","hint":""},{"id":"kv","title":"Var. €/St.","hint":""},{"id":"db","title":"db €/St.","hint":"Stück-DB = Nettoverkaufspreis − variable Kosten je Stück."},{"id":"max","title":"Max. Absatz","hint":""},{"id":"min","title":"min/St.","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Stück-DB ÷ min/St."},{"id":"rang","title":"Rang","hint":"Absteigend nach €/min ordnen."},{"id":"menge","title":"Produktion St.","hint":"Verteilen Sie die Kapazität in Rangfolge, höchstens bis zur Absatzgrenze."},{"id":"used","title":"Genutzte min","hint":"Produktionsmenge · min/St."}],"rows":[{"id":"basic","label":"Basic","given":{"preis":95,"kv":55,"max":400,"min":8},"expected":{"db":40,"rel":5,"rang":3,"menge":400,"used":3200},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"preis":145,"kv":80,"max":300,"min":10},"expected":{"db":65,"rel":6.5,"rang":2,"menge":300,"used":3000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"preis":190,"kv":110,"max":200,"min":20},"expected":{"db":80,"rel":4,"rang":4,"menge":40,"used":800},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"preis":240,"kv":135,"max":150,"min":15},"expected":{"db":105,"rel":7,"rang":1,"menge":150,"used":2250},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"p05","afb":2,"type":"number","prompt":"Wie viele Montageminuten werden vom optimalen Produktionsprogramm insgesamt genutzt?","answer":9250,"solution":"2.250 min (Pro) + 3.000 min (City) + 3.200 min (Basic) + 800 min (Studio) = <b>9.250 min</b>.","hint":"Kontrollieren Sie die genutzten Minuten je Modell."},{"id":"p06","afb":2,"type":"order","prompt":"Ordnen Sie die Arbeitsschritte der Engpassplanung in die richtige Reihenfolge.","answer":["rank","first","rest","next"],"solution":"1. Rangfolge anhand des relativen DB bilden → 2. obersten Rang bis maximaler Nachfrage berücksichtigen → 3. Restkapazität berechnen → 4. nächstes Produkt.","hint":"Bevor Sie produzieren, müssen Sie priorisieren.","items":[["next","Nächstes Produkt nach Rang wählen"],["rest","Restkapazität berechnen"],["rank","Rangfolge aus relativen DB bilden"],["first","Vorrangiges Produkt bis zur Absatzgrenze berücksichtigen"]]},{"id":"p07","afb":3,"type":"text","prompt":"Ein Unternehmen hat nur noch 53 Minuten für Produkt A (13 min/Stück). Die Absatzgrenze beträgt 8 Stück. Bestimmen und begründen Sie die zulässige Produktionsmenge und die verbleibende Zeit.","answer":"self","solution":"53 min (Restkapazität) ÷ 13 min/Stück = 4,0769…; es können nur <b>4 ganze Stück</b> hergestellt werden. Genutzte Zeit = 4 · 13 = <b>52 min</b>; Rest = <b>1 min</b>. Absatzgrenze 8 wird nicht überschritten.","hint":"Sie können keine Bruchteile von Produkten herstellen."},{"id":"p08","afb":3,"type":"matrix","prompt":"Neue Modellreihe: Für P, Q und R sind 2.520 min Maschinenzeit verfügbar. Ermitteln Sie relativen DB, Rang, optimale Produktionsmengen und genutzte Zeit in der Tabelle.","answer":{"p:rel":6,"p:rang":3,"p:menge":44,"p:used":660,"q:rel":8,"q:rang":1,"q:menge":120,"q:used":960,"r:rel":7,"r:rang":2,"r:menge":90,"r:used":900},"solution":"Q: 64 ÷ 8 = 8 €/min, 120 · 8 = 960 min; Rest 1.560 min. R: 70 ÷ 10 = 7 €/min, 90 · 10 = 900 min; Rest 660 min. P: 90 ÷ 15 = 6 €/min, 660 ÷ 15 = <b>44 St.</b>; Rest 0 min. <b>Gesamt-DB:</b> 120 · 64 + 90 · 70 + 44 · 90 = <b>17.940 €</b>.","hint":"Vergleichen Sie zuerst die drei DB je Minute. Die Absatzgrenzen legen die maximale mögliche Menge je Modell fest.","fields":["P (St.)","Q (St.)","R (St.)"],"grid":{"columns":[{"id":"db","title":"Stück-DB €/St.","hint":""},{"id":"min","title":"Zeit min/St.","hint":""},{"id":"max","title":"Max. Absatz","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Stück-DB ÷ Zeit je Stück."},{"id":"rang","title":"Rang","hint":"Nach relativen DB absteigend."},{"id":"menge","title":"Planmenge St.","hint":"Zuerst Rang 1 vollständig, dann Rang 2, dann verbleibende Kapazität."},{"id":"used","title":"Genutzte min","hint":"Menge · min/St."}],"rows":[{"id":"p","label":"P","given":{"db":90,"min":15,"max":80},"expected":{"rel":6,"rang":3,"menge":44,"used":660},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"q","label":"Q","given":{"db":64,"min":8,"max":120},"expected":{"rel":8,"rang":1,"menge":120,"used":960},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"r","label":"R","given":{"db":70,"min":10,"max":90},"expected":{"rel":7,"rang":2,"menge":90,"used":900},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}}]},{"id":"ergebnis","title":"Gesamt-DB und Betriebsergebnis","icon":"📊","lead":"Nach der Produktionsplanung bewerten Sie deren wirtschaftliches Ergebnis und überprüfen die Zahlen.","definition":"<b>Gesamtdeckungsbeitrag eines Produkts</b> = <b>produzierte und verkaufte Menge</b> · <b>Stückdeckungsbeitrag</b>. <b>Gesamt-DB des Programms</b> = Summe aller Produkt-DB. <b>Betriebsergebnis</b> = Gesamt-DB − <b>Fixkosten</b>. Bei positiven unveränderten Fixkosten führt das Programm mit dem höheren Gesamt-DB auch zum höheren Ergebnis.","example":"<b>Beispiel:</b> Studio: 40 Stück (optimale Menge) · 80,00 €/Stück (db) = <b>3.200,00 € DB</b>. Für alle vier Produkte: <b>54.450,00 €</b>. Abzüglich 38.000,00 € Fixkosten bleiben <b>16.450,00 € Gewinn</b>.","questions":[{"id":"g01","afb":1,"type":"matrix","prompt":"Ermitteln Sie die Gesamtdeckungsbeiträge der vier Modelle für das optimale Produktionsprogramm.","answer":{"basic:total":16000,"city:total":19500,"studio:total":3200,"pro:total":15750},"solution":"Basic: 400 · 40 = <b>16.000 €</b>; City: 300 · 65 = <b>19.500 €</b>; Studio: 40 · 80 = <b>3.200 €</b>; Pro: 150 · 105 = <b>15.750 €</b>.","hint":"Nur die tatsächlich geplante Produktionsmenge verwenden, nicht die maximale Absatzmenge.","grid":{"columns":[{"id":"menge","title":"Planmenge (St.)","hint":""},{"id":"db","title":"Stück-DB (€)","hint":""},{"id":"total","title":"Gesamt-DB (€)","hint":"Gesamt-DB je Modell = optimale Produktionsmenge · Stück-DB."}],"rows":[{"id":"basic","label":"Basic","given":{"menge":400,"db":40},"expected":{"total":16000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"menge":300,"db":65},"expected":{"total":19500},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"menge":40,"db":80},"expected":{"total":3200},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"menge":150,"db":105},"expected":{"total":15750},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"g02","afb":1,"type":"number","prompt":"Berechnen Sie den Gesamtdeckungsbeitrag von Pro.","answer":15750,"solution":"150 Stück (optimale Pro-Menge) · 105 €/Stück (Pro-db) = <b>15.750,00 €</b>.","hint":"Menge mal Stückdeckungsbeitrag."},{"id":"g03","afb":2,"type":"matrix","prompt":"Berechnen Sie für jedes Modell den Gesamt-DB und ergänzen Sie danach die Summe in der letzten Tabellenzeile.","answer":{"basic:total":16000,"city:total":19500,"studio:total":3200,"pro:total":15750,"summe:total":54450},"solution":"Basic: 400 · 40 = 16.000 €; City: 300 · 65 = 19.500 €; Studio: 40 · 80 = 3.200 €; Pro: 150 · 105 = 15.750 €. <b>Summe = 54.450 €</b>.","hint":"Berechnen Sie zunächst die Deckungsbeiträge je Modell; addieren Sie danach die vier Produktbeiträge.","grid":{"columns":[{"id":"menge","title":"Planmenge (St.)","hint":""},{"id":"db","title":"Stück-DB (€)","hint":""},{"id":"total","title":"Gesamt-DB (€)","hint":"Gesamt-DB je Modell = optimale Produktionsmenge · Stück-DB."}],"rows":[{"id":"basic","label":"Basic","given":{"menge":400,"db":40},"expected":{"total":16000},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"menge":300,"db":65},"expected":{"total":19500},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"menge":40,"db":80},"expected":{"total":3200},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"menge":150,"db":105},"expected":{"total":15750},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"summe","label":"SUMME","given":{},"expected":{"total":54450},"hint":"Addieren Sie die vier Gesamt-DB-Werte; Stückdeckungsbeiträge werden nicht einfach addiert."}]}},{"id":"g04","afb":2,"type":"number","prompt":"Ermitteln Sie das Betriebsergebnis bei 54.450 € Gesamtdeckungsbeitrag und monatlich 38.000 € Fixkosten.","answer":16450,"solution":"54.450 € (Gesamtdeckungsbeitrag) − 38.000 € (monatliche Fixkosten) = <b>16.450 € Gewinn</b>.","hint":"Gesamtdeckungsbeitrag minus Fixkosten."},{"id":"g05","afb":2,"type":"matrix","prompt":"Vervollständigen Sie die teilweise ausgefüllte Ergebnistabelle der LichtForm GmbH. Prüfen Sie die Werte je Modell und den gesamten DB.","answer":{"city:total":19500,"studio:total":3200,"pro:total":15750,"summe:total":54450},"solution":"Basic: 400 · 40 = 16.000 € (vorgegeben); City: 300 · 65 = <b>19.500 €</b>; Studio: 40 · 80 = <b>3.200 €</b>; Pro: 150 · 105 = <b>15.750 €</b>; <b>Summe: 54.450 €</b>.","hint":"Die Basic-Zeile ist ein Muster. Übertragen Sie das Verfahren auf die anderen drei Leuchten.","pairs":[["basic","16.000 €"],["city","19.500 €"],["studio","3.200 €"],["pro","15.750 €"]],"grid":{"columns":[{"id":"menge","title":"Planmenge (St.)","hint":""},{"id":"db","title":"Stück-DB (€)","hint":""},{"id":"total","title":"Gesamt-DB (€)","hint":"Gesamt-DB je Modell = optimale Produktionsmenge · Stück-DB."}],"rows":[{"id":"basic","label":"Basic","given":{"menge":400,"db":40,"total":16000},"expected":{},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"city","label":"City","given":{"menge":300,"db":65},"expected":{"total":19500},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"studio","label":"Studio","given":{"menge":40,"db":80},"expected":{"total":3200},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"pro","label":"Pro","given":{"menge":150,"db":105},"expected":{"total":15750},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"summe","label":"SUMME","given":{},"expected":{"total":54450},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"g06","afb":2,"type":"truefalse","prompt":"Die fixen Gesamtkosten werden bei unveränderter Höhe in der Rangfolge nach relativem DB bei einem einzigen Zeitengpass nicht pro Produkt abgezogen.","answer":true,"solution":"<b>Richtig.</b> Die Rangfolge ergibt sich aus dem Stück-DB je Engpasseinheit; unveränderte gemeinsame Fixkosten werden erst beim Betriebsergebnis berücksichtigt.","hint":"Fixkosten folgen erst nach der Summe aller Deckungsbeiträge."},{"id":"g07","afb":3,"type":"text","prompt":"Die Geschäftsführung fragt, warum im optimalen Produktionsprogramm trotz Rang 4 noch 40 Studio-Leuchten vorgesehen sind. Erläutern Sie das anhand der Restkapazität und des Gesamtdeckungsbeitrags.","answer":"self","solution":"Nach Pro (2.250 min), City (3.000 min) und Basic (3.200 min) bleiben <b>800 min</b> von 9.250 min Kapazität. Damit sind <b>40 Studio-Leuchten</b> (800 ÷ 20) möglich. Diese erwirtschaften 40 Stück · 80 €/St. = <b>3.200 € zusätzlichen Gesamt-DB</b>. Die anderen Modelle sind bereits an ihren Absatzgrenzen; ohne Studio würden die 800 min nicht genutzt und der Gesamt-DB wäre geringer.","hint":"Berechnen Sie die Restzeit nach Pro, City und Basic und ermitteln Sie, was Studio damit beitragen kann."},{"id":"g08","afb":3,"type":"number","prompt":"Der Vertrieb fertigt fälschlich nach dem höchsten Stück-DB: Pro 150 St., Studio 200 St., City 300 St., Basic 0 St. Ermitteln Sie den Ergebnisnachteil gegenüber dem optimalen Gesamt-DB von 54.450 €.","answer":3200,"solution":"Falscher Gesamt-DB = 150 · 105 € (Pro) + 200 · 80 € (Studio) + 300 · 65 € (City) = <b>51.250 €</b>. Ergebnisnachteil = 54.450 € (optimaler DB) − 51.250 € (falscher DB) = <b>3.200 €</b>.","hint":"Vergleichen Sie die Gesamtdeckungsbeiträge, weil die Fixkosten gleich sind."}]},{"id":"entscheiden","title":"Entscheidungen begründen","icon":"🧠","lead":"Sie sind nun in der Rolle einer Produktionsleitung: Berechnen reicht nicht immer. Sie müssen auch eine betriebswirtschaftlich nachvollziehbare Empfehlung formulieren.","definition":"<b>Wirtschaftliche Priorität:</b> Zuerst wird die knappe Kapazität für das Produkt mit dem <b>höchsten relativen DB</b> verwendet (bis zur Absatzgrenze). <b>Qualitative Kriterien</b> wie Kundenbeziehungen, Lieferfähigkeit, Qualität und Image können ergänzend relevant sein. Die berechnete optimale Lösung gilt für die <b>im Sachverhalt genannten Annahmen</b>.","example":"<b>Beispiel:</b> City erzielt 6,50 €/min und Studio 4,00 €/min. Bei knapper Montagezeit hat City Vorrang. Bei vertraglich zugesagten Lieferungen müssen aber auch Lieferpflichten geprüft werden.","questions":[{"id":"d01","afb":1,"type":"single","prompt":"Welche Kennzahl bestimmt die Vorrangstellung, wenn genau eine knappe Fertigungsressource vorhanden ist?","answer":"rel","solution":"Entscheidend ist der <b>relative Deckungsbeitrag pro Engpasseinheit</b>.","hint":"Welche Kennzahl setzt den DB zur knappen Ressource ins Verhältnis?","options":[["rel","Relativer Deckungsbeitrag"],["p","Höchster Nettoverkaufspreis"],["f","Fixkosten je Produkt"]]},{"id":"d02","afb":1,"type":"truefalse","prompt":"Wenn ausschließlich ganze Produkte gefertigt werden können, darf eine errechnete Produktionsmenge von 12,8 Stück auf 13 Stück aufgerundet werden, auch wenn dadurch die Zeitkapazität überschritten wird.","answer":false,"solution":"<b>Falsch.</b> Bei 12,8 möglichen Einheiten dürfen ohne zusätzliche Kapazität höchstens <b>12 ganze Stück</b> produziert werden.","hint":"Kapazitätsgrenzen sind verbindlich."},{"id":"d03","afb":2,"type":"number","prompt":"Bei 10.000 statt 9.250 verfügbaren Montageminuten: Wie viele Studio-Leuchten sind nach Pro (2.250 min), City (3.000 min) und Basic (3.200 min) vollständig produzierbar?","answer":77,"solution":"Rest = 10.000 min (neue Kapazität) − 2.250 min (Pro) − 3.000 min (City) − 3.200 min (Basic) = 1.550 min; 1.550 min ÷ 20 min/Studio = <b>77 ganze Stück</b> (10 min Rest).","hint":"Die anderen Absatzgrenzen bleiben gleich."},{"id":"d04","afb":2,"type":"multi","prompt":"Welche Aspekte sind neben der rein rechnerischen Rangfolge bei einer Produktionsentscheidung sinnvoll zu prüfen?","answer":["liefer","kunde","qual"],"solution":"<b>Lieferpflichten</b>, <b>Kundenbeziehungen</b> und <b>Qualitätsrisiken</b> können Entscheidungen beeinflussen. Die Lieblingsfarbe der Teamleitung ist kein sachliches betriebswirtschaftliches Kriterium.","hint":"Denken Sie an Risiken und Kunden.","options":[["liefer","Verbindliche Liefertermine"],["kunde","Langfristige Kundenbeziehungen"],["qual","Besondere Anforderungen an die Produktqualität"],["farbe","Persönlicher Farbgeschmack der Leitung"]]},{"id":"d05","afb":2,"type":"matrix","prompt":"Der Controllingbericht enthält nur Gesamtdeckungsbeiträge. Ermitteln Sie aus diesen Werten zunächst den Stück-DB und danach den relativen DB.","answer":{"helm-x:db":120,"helm-x:rel":15,"helm-y:db":110,"helm-y:rel":11,"helm-z:db":220,"helm-z:rel":11},"solution":"Helm X: 26.400 € (Gesamt-DB) ÷ 220 Stück = <b>120 €/St.</b>; 120 ÷ 8 = <b>15 €/min</b>. Helm Y: 18.700 ÷ 170 = <b>110 €/St.</b>; 110 ÷ 10 = <b>11 €/min</b>. Helm Z: 9.900 ÷ 45 = <b>220 €/St.</b>; 220 ÷ 20 = <b>11 €/min</b>.","hint":"Die erste Größe entsteht aus Gesamtdeckungsbeitrag geteilt durch Menge. Danach berechnen Sie den DB je knapper Minute.","grid":{"columns":[{"id":"gesamt","title":"Gesamt-DB (€)","hint":""},{"id":"anzahl","title":"Menge (St.)","hint":""},{"id":"min","title":"Zeit (min/St.)","hint":""},{"id":"db","title":"Stück-DB €/St.","hint":"Stück-DB = Gesamtdeckungsbeitrag ÷ produzierte Menge."},{"id":"rel","title":"Rel. DB €/min","hint":"Relativer DB = Stück-DB ÷ Zeit je Stück."}],"rows":[{"id":"helm-x","label":"Helm X","given":{"gesamt":26400,"anzahl":220,"min":8},"expected":{"db":120,"rel":15},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"helm-y","label":"Helm Y","given":{"gesamt":18700,"anzahl":170,"min":10},"expected":{"db":110,"rel":11},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"helm-z","label":"Helm Z","given":{"gesamt":9900,"anzahl":45,"min":20},"expected":{"db":220,"rel":11},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"d06","afb":2,"type":"matrix","prompt":"Ein weiterer Fertigungsbereich meldet andere Gesamtdeckungsbeiträge. Vergleichen Sie die Produktivität der drei Modelle in €/Montageminute.","answer":{"helm-a:db":120,"helm-a:rel":10,"helm-b:db":110,"helm-b:rel":11,"helm-c:db":180,"helm-c:rel":12},"solution":"Helm A: 12.000 ÷ 100 = 120 €/St.; 120 ÷ 12 = <b>10 €/min</b>. Helm B: 22.000 ÷ 200 = 110 €/St.; 110 ÷ 10 = <b>11 €/min</b>. Helm C: 27.000 ÷ 150 = 180 €/St.; 180 ÷ 15 = <b>12 €/min</b>.","hint":"Der größte Gesamtdeckungsbeitrag allein führt nicht zwangsläufig zum höchsten DB je Minute.","grid":{"columns":[{"id":"gesamt","title":"Gesamt-DB (€)","hint":""},{"id":"anzahl","title":"Menge (St.)","hint":""},{"id":"min","title":"Zeit (min/St.)","hint":""},{"id":"db","title":"Stück-DB €/St.","hint":"Stück-DB = Gesamtdeckungsbeitrag ÷ produzierte Menge."},{"id":"rel","title":"Rel. DB €/min","hint":"Relativer DB = Stück-DB ÷ Zeit je Stück."}],"rows":[{"id":"helm-a","label":"Helm A","given":{"gesamt":12000,"anzahl":100,"min":12},"expected":{"db":120,"rel":10},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"helm-b","label":"Helm B","given":{"gesamt":22000,"anzahl":200,"min":10},"expected":{"db":110,"rel":11},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"helm-c","label":"Helm C","given":{"gesamt":27000,"anzahl":150,"min":15},"expected":{"db":180,"rel":12},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"d07","afb":3,"type":"text","prompt":"Beurteilen Sie die Aussage: „Das gewinnoptimale Produktionsprogramm ist unabhängig von der Absatzgrenze; wir können stets nur das beste Modell herstellen.“","answer":"self","solution":"<b>Falsch.</b> Auch das vorrangige Produkt kann nur <b>bis zur maximal absetzbaren Menge</b> verkauft werden. Verbleibende Kapazität wird danach dem Produkt mit dem nächsthöheren relativen DB zugewiesen.","hint":"Berücksichtigen Sie Absatz und Kapazität gleichzeitig."},{"id":"d08","afb":3,"type":"text","prompt":"Die Marketingabteilung möchte alle vier Leuchtenmodelle trotz des Montageengpasses im Sortiment behalten. Beurteilen Sie diesen Wunsch aus absatzpolitischer Sicht anhand zweier qualitativer Kriterien.","answer":"self","solution":"Eine <b>breite Sortimentsauswahl</b> kann unterschiedliche Kundenwünsche erfüllen und die <b>Kundenbindung</b> stärken. Auch das <b>Image</b> als vielseitiger Anbieter kann relevant sein. Wirtschaftlich bleibt die Engpassrangfolge wichtig: Im optimalen Programm werden bereits <b>40 Studio-Leuchten</b> hergestellt, weil nach den vorrangigen Modellen noch <b>800 min</b> verfügbar sind. Eine abweichende Mengenverteilung müsste auf ihre Auswirkung auf den Gesamt-DB geprüft werden.","hint":"Denken Sie an Sortimentsvielfalt, Kundenwünsche und die wirtschaftliche Rangfolge; beachten Sie die noch möglichen 40 Studio-Stück."}]}],"bonus":[{"id":"x01","afb":2,"type":"number","prompt":"Bonus – Prüfanlage: 108.000 verfügbare Minuten. Wie viele Stunden sind das?","answer":1800,"solution":"108.000 min (Prüfkapazität) ÷ 60 min/h = <b>1.800 h</b>.","hint":"Minuten durch 60 teilen."},{"id":"x02","afb":2,"type":"number","prompt":"Bonus – Ein Rest von 1.275 min steht für ein Teil mit 10 min/Stück zur Verfügung. Wie viele ganze Teile können gefertigt werden?","answer":127,"solution":"1.275 min (Restzeit) ÷ 10 min/Stück = 127,5; es können <b>127 ganze Stück</b> gefertigt werden, 5 min bleiben frei.","hint":"Bruchteile dürfen nicht produziert werden."},{"id":"x03","afb":2,"type":"single","prompt":"Bonus – Bei 13 Stunden verfügbarer Fertigungszeit und 900 min Bedarf liegt …","answer":"eng","solution":"13 h · 60 min/h = 780 min; Bedarf 900 min > 780 min. <b>Es liegt ein Engpass von 120 min vor.</b>","hint":"Rechnen Sie zuerst die Stunden um.","options":[["kein","kein Engpass vor"],["eng","ein Engpass von 120 min vor"],["eng2","ein Engpass von 13 min vor"]]},{"id":"x04","afb":3,"type":"text","prompt":"Bonus – Ein Produktionsleiter lässt ausschließlich das Produkt mit dem höchsten relativen DB fertigen und nutzt dadurch nur die Hälfte der vorhandenen Zeit. Entwickeln Sie eine bessere Vorgehensweise.","answer":"self","solution":"Er muss zuerst das vorrangige Produkt <b>bis zur Absatzgrenze</b> einplanen und anschließend die <b>verbleibende Restkapazität</b> schrittweise mit den Produkten der nächsten Ränge belegen, sofern deren Stück-DB positiv und Absatz vorhanden ist. Eine reine Beschränkung auf Rang 1 verschenkt DB.","hint":"Der erste Rang ist ein Anfang, nicht das Ende der Planung."},{"id":"x05","afb":3,"type":"matrix","prompt":"Bonus: Eine Zubehörfertigung hat 594 min Kapazität. Planen Sie die Produkte A, B und C und ergänzen Sie die Tabelle einschließlich Rang, Menge und Zeit.","answer":{"a:rel":8,"a:rang":1,"a:menge":60,"a:used":240,"b:rel":5,"b:rang":3,"b:menge":16,"b:used":144,"c:rel":8,"c:rang":1,"c:menge":70,"c:used":210},"solution":"A und C: 32 ÷ 4 = 24 ÷ 3 = <b>8 €/min</b>, gemeinsam 60 · 4 + 70 · 3 = 450 min. Rest 594 − 450 = 144 min. B: 45 ÷ 9 = <b>5 €/min</b>, 144 ÷ 9 = <b>16 Stück</b>. Genutzte Zeit = <b>594 min</b>. Gleichrangige Modelle A und C können in beliebiger Reihenfolge berücksichtigt werden.","hint":"A und C haben denselben DB je Minute. Beide können zuerst bis zu ihrer jeweiligen Absatzgrenze eingeplant werden.","fields":["A (St.)","B (St.)","C (St.)"],"grid":{"columns":[{"id":"db","title":"Stück-DB €/St.","hint":""},{"id":"min","title":"Zeit min/St.","hint":""},{"id":"max","title":"Max. Absatz","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Stück-DB ÷ Zeit je Stück."},{"id":"rang","title":"Rang","hint":"Nach relativen DB absteigend."},{"id":"menge","title":"Planmenge St.","hint":"Zuerst Rang 1 vollständig, dann Rang 2, dann verbleibende Kapazität."},{"id":"used","title":"Genutzte min","hint":"Menge · min/St."}],"rows":[{"id":"a","label":"A","given":{"db":32,"min":4,"max":60},"expected":{"rel":8,"rang":1,"menge":60,"used":240},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"b","label":"B","given":{"db":45,"min":9,"max":50},"expected":{"rel":5,"rang":3,"menge":16,"used":144},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"c","label":"C","given":{"db":24,"min":3,"max":70},"expected":{"rel":8,"rang":1,"menge":70,"used":210},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"x06","afb":3,"type":"text","prompt":"Bonus – Die Produktionsleitung möchte ausschließlich die beiden Leuchten mit den höchsten Nettoverkaufspreisen fertigen. Widerlegen oder bestätigen Sie diesen Vorschlag rechnerisch mithilfe der relativen Deckungsbeiträge und nennen Sie ein absatzpolitisches Risiko.","answer":"self","solution":"<b>Die beiden höchsten Preise</b> haben Pro (240 €/St.) und Studio (190 €/St.). Entscheidend ist jedoch der <b>relative DB</b>: Pro 105 € ÷ 15 min = <b>7,00 €/min</b>; City 65 € ÷ 10 min = <b>6,50 €/min</b>; Basic 40 € ÷ 8 min = <b>5,00 €/min</b>; Studio 80 € ÷ 20 min = <b>4,00 €/min</b>. Daher wäre „nur Pro und Studio“ keine sinnvolle Engpassstrategie. <b>Absatzpolitisch</b> drohen bei Konzentration auf zwei Modelle der Verlust von Kundengruppen und geringere Sortimentsvielfalt. Nach der Absatzgrenze von Pro müssen weitere Modelle entsprechend ihrer relativen DB berücksichtigt werden.","hint":"Ermitteln Sie zuerst die beiden höchsten Verkaufspreise und vergleichen Sie diese Entscheidung anschließend mit dem DB je Montageminute."},{"id":"x07","afb":2,"type":"number","prompt":"Bonus – Bei 3.600 min Kapazität werden 450 Stück eines Produkts mit 6 min/Stück gefertigt. Wie viel Restkapazität bleibt?","answer":900,"solution":"3.600 min (Kapazität) − 450 Stück (Menge) · 6 min/Stück = <b>900 min</b>.","hint":"Benötigte Zeit abziehen."},{"id":"x08","afb":3,"type":"text","prompt":"Bonus – Erklären Sie, warum das Verfahren „höchster relativer DB zuerst“ nur bei passenden Annahmen zuverlässig ist und eine Produktion ganzer Stückzahlen zusätzliche Kontrollen verlangt.","answer":"self","solution":"Das Rangverfahren setzt insbesondere einen <b>einzigen relevanten Engpass</b>, bekannte konstante Stück-DB und Zeitbedarfe sowie begrenzte Absatzmengen voraus. Bei <b>ganzen Stückzahlen</b> können Restminuten entstehen; das Ergebnis muss auf Kapazitätsgrenzen und gegebenenfalls alternative Kombinationen geprüft werden.","hint":"Denken Sie an Annahmen des Modells und an Rundungen."}],"final":[{"id":"t01","afb":1,"type":"number","prompt":"Ein Produkt wird für 160 € verkauft, variable Stückkosten sind 94 €. Ermitteln Sie den Stück-DB.","answer":66,"solution":"160 € (Nettoverkaufspreis) − 94 € (variable Stückkosten) = <b>66 €/Stück</b>.","hint":"Preis minus variable Kosten."},{"id":"t02","afb":1,"type":"single","prompt":"Was bedeutet „relativer Deckungsbeitrag“?","answer":"pro","solution":"Stückdeckungsbeitrag <b>je Engpasseinheit</b>.","hint":"Gesucht wird eine Verhältniszahl.","options":[["fix","Fixkosten je Stück"],["pro","Stückdeckungsbeitrag je Engpasseinheit"],["ges","Summe aller Verkaufspreise"]]},{"id":"t03","afb":2,"type":"number","prompt":"Die Nachfrage beträgt 180 Stück bei 9 min/Stück. Wie viel Minuten werden bei maximalem Absatz benötigt?","answer":1620,"solution":"180 Stück (maximaler Absatz) · 9 min/Stück = <b>1.620 min</b>.","hint":"Menge mal Stückzeit."},{"id":"t04","afb":2,"type":"number","prompt":"Bei 6.750 min Gesamtbedarf sind 5.800 min vorhanden. Ermitteln Sie den Fehlbedarf (min).","answer":950,"solution":"6.750 min (Bedarf) − 5.800 min (Kapazität) = <b>950 min</b>.","hint":"Bedarf abzüglich Kapazität."},{"id":"t05","afb":2,"type":"order","prompt":"Ein Produktionsmix hat folgende relative DB: A 4 €/min, B 7 €/min, C 5 €/min. Ordnen Sie die optimale Reihenfolge.","answer":["b","c","a"],"solution":"<b>B → C → A</b>, weil 7 > 5 > 4 €/min.","hint":"Absteigend ordnen.","items":[["a","A: 4 €/min"],["b","B: 7 €/min"],["c","C: 5 €/min"]]},{"id":"t06","afb":2,"type":"number","prompt":"Für Produkt B bleiben 460 min übrig. Ein Stück braucht 12 min. Wie viele ganze Stück können gefertigt werden?","answer":38,"solution":"460 min (Restkapazität) ÷ 12 min/Stück = 38,33; <b>38 ganze Stück</b>, Rest 4 min.","hint":"Nicht aufrunden."},{"id":"t07","afb":2,"type":"multi","prompt":"Welche drei Kontrollen gehören zum optimalen Produktionsprogramm?","answer":["kap","abs","db"],"solution":"<b>Kapazitätsgrenze</b> einhalten, <b>Absatzgrenzen</b> einhalten und den <b>Gesamtdeckungsbeitrag</b> aus Mengen und Stück-DB ermitteln.","hint":"Prüfen Sie Zeit, Markt und Ergebnis.","options":[["kap","Genutzte Kapazität ≤ verfügbare Kapazität"],["abs","Produzierte Menge ≤ Absatzgrenze"],["preis","Höchster Stückpreis muss immer zuerst produziert werden"],["db","Gesamt-DB = Summe Menge · Stück-DB"]]},{"id":"t08","afb":3,"type":"matrix","prompt":"Abschlusstest: Drei Produkte konkurrieren um 1.200 min Prüfzeit. Ermitteln Sie die relative Rangfolge, Produktionsmengen und genutzten Minuten.","answer":{"a:rel":6,"a:rang":2,"a:menge":100,"a:used":800,"b:rel":10,"b:rang":1,"b:menge":80,"b:used":400,"c:rel":5,"c:rang":3,"c:menge":0,"c:used":0},"solution":"B: 50 ÷ 5 = 10 €/min; 80 · 5 = <b>400 min</b>. A: 48 ÷ 8 = 6 €/min; 100 · 8 = <b>800 min</b>. C: 45 ÷ 9 = 5 €/min, aber <b>0 Stück</b>, da keine Kapazität bleibt. Summe: <b>1.200 min</b>, Gesamt-DB: 80 · 50 + 100 · 48 = <b>8.800 €</b>.","hint":"Tragen Sie zuerst die relativen Deckungsbeiträge ein; verteilen Sie danach die 1.200 Minuten ab Rang 1.","fields":["A (St.)","B (St.)","C (St.)"],"grid":{"columns":[{"id":"db","title":"Stück-DB €/St.","hint":""},{"id":"min","title":"Zeit min/St.","hint":""},{"id":"max","title":"Max. Absatz","hint":""},{"id":"rel","title":"Rel. DB €/min","hint":"Stück-DB ÷ Zeit je Stück."},{"id":"rang","title":"Rang","hint":"Nach relativen DB absteigend."},{"id":"menge","title":"Planmenge St.","hint":"Zuerst Rang 1 vollständig, dann Rang 2, dann verbleibende Kapazität."},{"id":"used","title":"Genutzte min","hint":"Menge · min/St."}],"rows":[{"id":"a","label":"A","given":{"db":48,"min":8,"max":100},"expected":{"rel":6,"rang":2,"menge":100,"used":800},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"b","label":"B","given":{"db":50,"min":5,"max":80},"expected":{"rel":10,"rang":1,"menge":80,"used":400},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."},{"id":"c","label":"C","given":{"db":45,"min":9,"max":80},"expected":{"rel":5,"rang":3,"menge":0,"used":0},"hint":"Wählen Sie die passende Formel und setzen Sie ausschließlich die Angaben aus dieser Zeile ein."}]}},{"id":"t09","afb":3,"type":"number","prompt":"Mit dem Programm aus der vorigen Testaufgabe entstehen 8.800 € Gesamtdeckungsbeitrag. Bei 6.200 € Fixkosten: Berechnen Sie das Betriebsergebnis.","answer":2600,"solution":"8.800 € (vorgegebener Gesamt-DB) − 6.200 € (Fixkosten) = <b>2.600 € Gewinn</b>.","hint":"Beide Werte stehen in dieser Frage."},{"id":"t10","afb":3,"type":"text","prompt":"Eine Geschäftsführung will aufgrund des höchsten Stück-DB nur noch Produkt A fertigen, obwohl Produkt B pro Minute mehr DB erzielt. Beurteilen Sie den Vorschlag bei begrenzter Maschinenzeit.","answer":"self","solution":"Die Entscheidung allein nach Stück-DB ist <b>nicht begründet</b>. Bei einem einzigen Maschinenengpass ist der <b>DB je Minute</b> entscheidend. Das Produkt B ist bei höherem relativem DB vorrangig (bis zur Absatzgrenze); danach werden weitere Produkte der Rangfolge berücksichtigt.","hint":"Beziehen Sie sich auf die Engpasseinheit."}],"glossary":[["Deckungsbeitrag","Der Betrag, der nach Abzug der variablen Kosten vom Umsatz zur Deckung der Fixkosten bleibt."],["Stückdeckungsbeitrag","Nettoverkaufspreis je Stück abzüglich variabler Stückkosten."],["Relativer Deckungsbeitrag","Stückdeckungsbeitrag je Engpasseinheit; bei Montagezeit: €/Minute oder €/Stunde."],["Engpass","Eine knappe Ressource, deren vorhandene Kapazität für den gesamten Bedarf nicht ausreicht."],["Engpasseinheit","Maßeinheit der knappen Ressource, etwa Montagestunde, Prüfminute oder Kilogramm Material."],["Absatzgrenze","Maximale Menge, die ein Unternehmen im betrachteten Zeitraum absetzen kann."],["Kapazität","Menge bzw. Zeit, die einer Produktionseinrichtung zur Verfügung steht."],["Restkapazität","Noch nicht genutzter Teil der verfügbaren Kapazität nach eingeplanten Produkten."],["Optimales Produktionsprogramm","Die gewinnorientierte Mengenverteilung, die bei begrenzter Kapazität den Gesamtdeckungsbeitrag maximiert."],["Gesamtdeckungsbeitrag","Summe der einzelnen Produktdeckungsbeiträge: Produktionsmenge mal Stückdeckungsbeitrag."],["Betriebsergebnis","Gesamter Deckungsbeitrag abzüglich Fixkosten."],["Fixkosten","Kosten, die innerhalb des betrachteten Beschäftigungsbereichs unabhängig von der Ausbringungsmenge anfallen."],["Variable Kosten","Kosten, die sich bei proportionalem Kostenverlauf mit der gefertigten Menge verändern."],["Rangfolge","Reihenfolge der Produkte nach absteigendem relativen Deckungsbeitrag."]],"checklist":["Ich kann Stückdeckungsbeiträge aus Preisen und variablen Kosten berechnen.","Ich kann einen Engpass aus Bedarf und vorhandener Kapazität erkennen.","Ich kann Stunden und Minuten sicher umrechnen.","Ich kann den relativen Deckungsbeitrag je Engpasseinheit berechnen.","Ich kann Produkte nach relativem Deckungsbeitrag ordnen.","Ich kann ein Produktionsprogramm unter Absatzgrenzen ermitteln.","Ich kann die Restkapazität nach jedem Produkt berechnen.","Ich kann Gesamtdeckungsbeitrag und Betriebsergebnis ermitteln.","Ich kann falsche Priorisierungen rechnerisch widerlegen.","Ich kann eine Entscheidung auch mit qualitativen Kriterien begründen."],"date":"10.11.2026","shop":[{"id":"start","label":"Werkstattstarter","emoji":"🧑‍🏭","kind":"Avatar","cost":0,"description":"Ihr erster Produktionsprofi."},{"id":"fox","label":"Fuchs-Avatar","emoji":"🦊","kind":"Avatar","cost":120,"description":"Clever wie eine gute Engpassplanung."},{"id":"robot","label":"Roboter-Avatar","emoji":"🤖","kind":"Avatar","cost":200,"description":"Die analytische Produktionsleitung."},{"id":"astronaut","label":"Space-Controller","emoji":"👩‍🚀","kind":"Avatar","cost":320,"description":"Planung bis in die Sterne."},{"id":"cat","label":"Bürokatze","emoji":"🐈","kind":"Haustier","cost":80,"description":"Schaut über Ihre Zahlen."},{"id":"owl","label":"Zahlen-Eule","emoji":"🦉","kind":"Haustier","cost":150,"description":"Bleibt auch bei Engpässen wach."},{"id":"dragon","label":"Produktionsdrache","emoji":"🐉","kind":"Haustier","cost":260,"description":"Legendärer Begleiter."},{"id":"helmet","label":"Goldener Helm","emoji":"👑","kind":"Outfit","cost":180,"description":"Der Klassiker für Controller."},{"id":"coat","label":"Laborkittel","emoji":"🥼","kind":"Outfit","cost":100,"description":"Für die Wissenschaft der Kosten."}],"gameRules":{"visualCards":20,"title":"Zeitkarten-Challenge","teamInstruction":"Bearbeiten Sie die Aufgabe zu zweit: Person A plant, Person B prüft. Tauschen Sie danach die Rollen und geben Sie gemeinsam ab."}};
